import math

from qiskit import QuantumCircuit
from qiskit.quantum_info import DensityMatrix, Pauli, Statevector, partial_trace
from qiskit.visualization.state_visualization import _bloch_multivector_data

# The five circuits MUST mirror data/figures/s2-q047/generate.py — the rendered
# figures are plot_bloch_multivector drawings of exactly these states.

T = 2 * math.pi / 3


def state(*gates):
    qc = QuantumCircuit(2)
    for name, *args in gates:
        getattr(qc, name)(*args)
    return Statevector(qc)


def stem_state():
    return state(("ry", T, 0), ("cx", 0, 1), ("h", 1))


VARIANTS = {
    "A": state(("ry", T, 1), ("cx", 1, 0), ("h", 0)),
    "B": stem_state(),
    "C": state(("x", 0), ("x", 1), ("h", 1)),
    "D": state(("ry", T, 0), ("h", 1)),
    "E": state(("ry", T, 0), ("cx", 0, 1), ("x", 1), ("h", 1)),
}


def spheres(st):
    """One Bloch vector per sphere the drawer puts on the figure (x, y, z)."""
    rho = DensityMatrix(st)
    n = len(rho.dims())
    out = []
    for i in range(n):
        red = partial_trace(rho, [j for j in range(n) if j != i])
        out.append(tuple(
            round(float(red.expectation_value(Pauli(p)).real), 3) + 0.0 for p in "XYZ"
        ))
    return tuple(out)


def drawer_vectors(st):
    """The vectors plot_bloch_multivector itself hands to each sphere (pinned helper)."""
    return tuple(tuple(round(float(c), 3) + 0.0 for c in v) for v in _bloch_multivector_data(st))


def length(v):
    return round(math.sqrt(sum(c * c for c in v)), 3)


target = spheres(stem_state())
# Sanity: the stem state is entangled, so both drawn arrows are shorter than 1.
assert all(length(v) < 0.99 for v in target), target
proven, evidence, observed = [], {}, {}
for key, st in sorted(VARIANTS.items()):
    s = spheres(st)
    drawn = drawer_vectors(st)
    # the drawer's own data must agree with the partial-trace computation
    assert drawn == s, (key, drawn, s)
    match = s == target
    observed[key] = [list(v) for v in s]
    evidence[key] = (
        f"figure draws Bloch vectors (x, y, z) qubit 0 {s[0]} len {length(s[0])}, "
        f"qubit 1 {s[1]} len {length(s[1])} (same as plot_bloch_multivector's own "
        f"_bloch_multivector_data: {drawn == s}) vs the stem's {list(target)} -> match={match}"
    )
    if match:
        proven.append(key)

observed["stem"] = [list(v) for v in target]
observed["stem_probabilities"] = {
    k: round(float(v), 3) for k, v in stem_state().probabilities_dict().items()
}
emit_verdict({"answer": proven, "evidence": evidence, "observed": observed})
